        sampler.addAndMakeVisible(sampleMode);const juce::StringArray modes{"Classic / gate","One-shot","Slices"};sampleMode.addItemList(modes,1);Localisation::bindItems(sampleMode,modes);Localisation::bindTip(sampleMode,"Gate follows key length; one-shot plays to the end; slices maps each detected piece to a separate key.");sampleMode.onChange=[this]{const int mode=sampleMode.getSelectedId()-1;if(updating||!selected()||selected()->sampler.mode==mode)return;owner.checkpoint();selected()->sampler.mode=mode;if(mode==2&&selected()->sampler.sliceCount==0){sliceSample(false);return;}commit();};


